args.sparql:
SELECT ?director ?directorLabel ?deathPlace ?deathPlaceLabel WHERE {
  <http://dbpedia.org/resource/Ave_Caesar!> dbo:director ?director .
  ?director dbo:deathPlace ?deathPlace .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER (lang(?deathPlaceLabel) = 'en') }
}

